import { afterAll, beforeAll, expect, it, vi } from "vitest";
vi.mock("@/lib/logger", async () => (await import("./_support/doubles/misc")).loggerModule);
import { subscribe } from "@/lib/event-bus";
import * as svc from "@/server/services/organization-service";
import * as sess from "@/server/services/session-service";
import * as orgRepo from "@/server/repositories/organization-repository";
import { createTenant, useTemporaryDatabase } from "./_support/fixtures";
let cleanup: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); });
afterAll(() => cleanup());
it("works", async () => {
  const t = await createTenant("ren");
  const old = t.org.slug;
  const seen: unknown[] = [];
  subscribe("organization.slug_changed", (p) => { seen.push(p); });
  const r = await svc.renameOrganizationSlug(t.actors.admin, { orgId: t.org.id, slug: "brand-new" });
  expect(r.slug).toBe("brand-new");
  expect((await orgRepo.findOrgBySlug(old))?.id).toBe(t.org.id);
  expect(seen).toHaveLength(1);
  await svc.renameOrganizationSlug(t.actors.admin, { orgId: t.org.id, slug: "brand-new" });
  expect(seen).toHaveLength(1);
  const taken = await orgRepo.listTakenOrgSlugs(old);
  expect(taken).toContain(old);
  vi.useFakeTimers(); vi.setSystemTime(Date.now() + 30 * 86400000 + 1000);
  expect(await orgRepo.findOrgBySlug(old)).toBeNull();
  vi.useRealTimers();
  await expect(svc.renameOrganizationSlug(t.actors.member, { orgId: t.org.id, slug: "zzz-x" })).rejects.toThrow();
  const back = await svc.renameOrganizationSlug(t.actors.admin, { orgId: t.org.id, slug: old });
  expect(back.slug).toBe(old);
  expect((await orgRepo.findOrgBySlug("brand-new"))?.id).toBe(t.org.id);
  void sess;
});
EOF
